"""Render the private assessment report from its reviewed source files."""
import html
import json
from pathlib import Path

BASE = Path(__file__).resolve().parent
data = json.loads((BASE / 'review.source.json').read_text())
brief = (BASE / 'turing-brief.md').read_text()
esc = html.escape

steps = ''.join(f'<li><span class="step">{i + 1:02}</span><h3>{esc(s["title"])}</h3><p>{esc(s["body"])}</p></li>' for i, s in enumerate(data['bridge']['steps']))
hard_parts = ''.join(f'<li>{esc(s)}</li>' for s in data['bridge']['hard_parts'])
examples = ''.join(f'''<article class="case"><p class="eyebrow">{esc(e['date'])} · {esc(e['commit'][:8])}</p><h3>{esc(e['name'])}</h3><p>{esc(e['summary'])}</p><a href="evidence.md#case-{i+1}">Source and proof limits ↗</a></article>''' for i, e in enumerate(data['historical_change_examples']))
prices = ''.join(f'<tr><td>{esc(p["material"])}</td><td>{esc(p["published"])}</td></tr>' for p in data['published_prices']['rows'])
questions = ''.join(f'<li>{esc(q)}</li>' for q in data['buyer_questions'])
embedded = json.dumps({'source': data, 'brief': brief}, ensure_ascii=False).replace('<', '\\u003c')

template = '''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="color-scheme" content="light"><title>Prospect Pipeline · assessment pack · 15 October 2026</title>
<style>
:root{--ink:#172d36;--muted:#4e646b;--paper:#f4f3ed;--line:#cbd6d2;--accent:#166450;--wash:#e7f0e9;--white:#fffefa}
*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:18px/1.55 system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}main{max-width:1120px;margin:auto;padding:40px 32px 64px}a{color:var(--accent);text-underline-offset:4px}a:hover{text-decoration-thickness:2px}button{font:inherit;cursor:pointer}button:focus-visible,a:focus-visible,summary:focus-visible{outline:3px solid #216dde;outline-offset:4px}h1{font-size:clamp(36px,5vw,64px);line-height:1.08;letter-spacing:-.045em;max-width:820px;margin:16px 0 22px}h2{font-size:29px;line-height:1.25;letter-spacing:-.025em;margin:0 0 16px}h3{font-size:21px;line-height:1.3;margin:12px 0}p{margin:0 0 16px}.eyebrow{font-size:13px;letter-spacing:.12em;text-transform:uppercase;font-weight:750;color:var(--muted)}.intro{font-size:21px;max-width:760px}.stamp{display:flex;gap:18px;flex-wrap:wrap;align-items:center}.badge{background:var(--wash);color:var(--accent);border:1px solid #b6d0bf;border-radius:30px;padding:5px 12px;font-size:14px;font-weight:650}.tabs{display:flex;border-bottom:1px solid var(--line);gap:5px;margin:32px 0}.tabs button{border:0;background:none;color:var(--muted);padding:15px 18px;border-bottom:4px solid transparent}.tabs button[aria-selected="true"]{color:var(--ink);border-bottom-color:var(--accent);font-weight:750}.panel{animation:appear .15s ease-out}.panel[hidden]{display:none}@keyframes appear{from{opacity:.6}to{opacity:1}}.flow{display:grid;grid-template-columns:repeat(4,1fr);list-style:none;padding:0;gap:12px;margin:24px 0}.flow li{background:var(--white);border:1px solid var(--line);border-top:4px solid var(--accent);border-radius:8px;padding:22px 18px;position:relative}.flow li:nth-child(2){background:var(--wash)}.flow p{font-size:17px;margin:0}.step{font-size:14px;font-weight:800;color:var(--accent)}.split{display:grid;grid-template-columns:1.1fr 1fr;gap:30px;margin:30px 0}.note{background:var(--white);border:1px solid var(--line);border-radius:10px;padding:24px}.note p:last-child{margin:0}.plain-list{padding-left:22px;margin:0}.plain-list li{margin-bottom:9px}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:24px 0}.metric{padding:18px;border:1px solid var(--line);border-radius:8px;background:var(--white)}.metric strong{display:block;font-size:35px;letter-spacing:-.04em;font-variant-numeric:tabular-nums}.metric span{font-size:15px;color:var(--muted)}.cases{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.case{padding:24px;border:1px solid var(--line);border-radius:8px;background:var(--white)}.case p{font-size:17px}.case a{font-size:16px}.small{font-size:15px;color:var(--muted)}details{border-top:1px solid var(--line);padding:18px 0;margin-top:16px}summary{cursor:pointer;font-weight:700}details>div{padding-top:18px}table{border-collapse:collapse;width:100%;font-size:16px}th,td{text-align:left;border-bottom:1px solid var(--line);padding:12px 8px;vertical-align:top}th{font-size:14px;color:var(--muted)}.actions{display:flex;flex-wrap:wrap;gap:10px;margin:20px 0}.actions button{border:1px solid var(--line);border-radius:6px;padding:10px 15px;background:var(--white);color:var(--ink);font-size:16px}.actions button.primary{background:var(--accent);color:white;border-color:var(--accent)}.brief{white-space:pre-wrap;font-family:inherit;font-size:17px;line-height:1.6;overflow-wrap:anywhere;background:var(--white);border:1px solid var(--line);border-radius:8px;padding:24px;max-width:850px}.status{min-height:28px;color:var(--accent);font-size:15px}footer{margin-top:36px;border-top:1px solid var(--line);padding-top:22px;display:flex;gap:18px;flex-wrap:wrap;font-size:15px}code{font-size:.9em;overflow-wrap:anywhere}@media(max-width:760px){.tabs{display:grid;grid-template-columns:1fr 1fr}.tabs button{text-align:left}main{padding:24px 18px 40px}.flow{grid-template-columns:1fr 1fr}.split,.cases{grid-template-columns:1fr}.metrics{grid-template-columns:1fr 1fr}.tabs button{padding:13px 9px;font-size:16px}.intro{font-size:19px}.brief{padding:18px;font-size:16px}h2{font-size:25px}}@media(max-width:430px){.flow{grid-template-columns:1fr}.flow li{padding:16px 18px}.flow h3{margin:4px 0 8px}.tabs{gap:0;justify-content:space-between}}@media(prefers-reduced-motion:reduce){.panel{animation:none}}@media print{body{background:white;font-size:11pt}main{max-width:none;padding:0}h1{font-size:30pt}.tabs,.actions,.status{display:none!important}.panel[hidden]{display:block!important}.panel{margin-top:30px;break-before:page}.panel:first-of-type{break-before:auto}.flow{grid-template-columns:repeat(4,1fr)}.cases{grid-template-columns:1fr}.case,.note,.metric{break-inside:avoid}details>div{display:block!important}details{break-inside:avoid}.brief{white-space:pre-wrap}.small{font-size:10pt}a{color:inherit}}
</style></head><body><main>
<header><div class="stamp"><span class="eyebrow">Singleton Systems · 15 October 2026</span><span class="badge">Internal review</span></div><h1>The work behind<br>the bridge.</h1><p class="intro">Jerami built a FastAPI bridge that made a custom Laravel system usable through clean JSON and Raycast. The history of that work is the package to assess.</p></header>
<nav class="tabs" aria-label="Review sections"><button id="tab-bridge" data-panel="bridge">1. The bridge</button><button id="tab-proof" data-panel="proof">2. The proof</button><button id="tab-buyer" data-panel="buyer">3. The buyer</button><button id="tab-split" data-panel="split">4. The split</button></nav>
<section class="panel" id="bridge" aria-labelledby="tab-bridge"><h2>Your work sits in the middle.</h2><ol class="flow">@@STEPS@@</ol>
<div class="split"><div><h3>The hard parts</h3><ul class="plain-list">@@HARD@@</ul></div><aside class="note"><h3>Who built what</h3><p>Jerami designed and built the surrounding system. He also created or pitched the video progress page.</p><p>Prospect ID supplied the old backend and company work records. Jerami reports an independent-contractor arrangement with no code ownership assignment.</p></aside></div>
<p class="small">The proposed value: real problems, fixes, and checks that could help train or test AI on older business software. A buyer has not assessed this archive.</p></section>
<section class="panel" id="proof" aria-labelledby="tab-proof"><h2>Real repairs with a source trail.</h2><p>Each example points to an actual code change. Live backend replay was outside this review.</p>
<div class="cases">@@EXAMPLES@@</div>
<div class="metrics"><div class="metric"><strong>408</strong><span>current-branch commits</span></div><div class="metric"><strong>75</strong><span>bridge routes</span></div><div class="metric"><strong>22</strong><span>AI co-author credits</span></div><div class="metric"><strong>80</strong><span>local tests passed</span></div></div>
<details><summary>The records behind the work</summary><div><table><thead><tr><th>Record</th><th>Verified amount</th></tr></thead><tbody><tr><td>Video tasks</td><td>34 historical snapshots; 1,163 distinct task IDs.</td></tr><tr><td>Sales backfill</td><td>723 rows parsed from saved SQL.</td></tr><tr><td>Separate event contract</td><td>928 events; 928 distinct event keys.</td></tr><tr><td>Message audit</td><td>Saved audit reports 566 messages processed and five proposed follow-up actions.</td></tr><tr><td>AI work</td><td>Commit credits, saved agent briefs, repair notes, and Raycast AI draft code.</td></tr></tbody></table><p class="small">Sources overlap. Snapshots preserve states. The source appendix defines each count. <a href="evidence.md">Read the evidence</a>.</p></div></details>
<details><summary>How the facts were checked</summary><div><p>The census covers 1,010 historical non-build paths. Eligible text versions were scanned in memory. Three historical repairs have before/after source references.</p><p>The existing TypeScript checks passed 80 tests. The expanded Python run passed 29 of 35 fixtures; six owner/calendar checks fail against the demo configuration.</p><p><a href="review.source.json">Source facts</a> · <a href="composition-audit.json">File census</a> · <a href="verification.md">Verification record</a></p></div></details></section>
<section class="panel" id="buyer" aria-labelledby="tab-buyer"><h2>Get a fit decision from Turing.</h2><p>The first form needs no files. Use this brief for the follow-up call or email.</p><div class="actions"><button class="primary" id="copy-brief">Copy brief</button><button id="save-brief">Download brief</button><button id="save-facts">Download source facts</button><button id="print-report">Print report</button></div><p class="status" role="status" id="status"></p><div class="brief" id="brief-text">@@BRIEF@@</div>
<details><summary>Published prices and questions to ask</summary><div><table><thead><tr><th>Material</th><th>Turing's published figures</th></tr></thead><tbody>@@PRICES@@</tbody></table><p class="small">Source: <a href="https://www.turing.com/blog/agi-advance-newsletter-57" target="_blank" rel="noopener noreferrer">Turing newsletter</a>. Its dates conflict. The <a href="https://lazarus.turing.com/" target="_blank" rel="noopener noreferrer">current program</a> quotes after sampling and does not buy code alone. These figures do not price this archive. Payment timing is unconfirmed.</p><ul class="plain-list">@@QUESTIONS@@</ul></div></details>
<p class="small"><a href="https://lazarus.turing.com/get-in-touch" target="_blank" rel="noopener noreferrer">Turing intake ↗</a> · <a href="buyer-drafts.md">Mercor and Defined.ai drafts</a></p></section>
<section class="panel" id="split" aria-labelledby="tab-split"><h2>The file count supports your point.</h2><p>Across 1,010 historical non-build paths, implementation and supporting work occupy most files.</p><table><thead><tr><th>File role</th><th>Paths</th><th>Share</th></tr></thead><tbody><tr><td>Implementation and support</td><td>896</td><td>88.7%</td></tr><tr><td>Company-record artifacts</td><td>30</td><td>3.0%</td></tr><tr><td>Other material</td><td>84</td><td>8.3%</td></tr></tbody></table><p class="small">This measures file roles. Some authored source also contains company examples. File counts do not set legal ownership or sale value.</p><div class="split"><div class="note"><p class="eyebrow">My opening proposal · $10,000 combined license</p><h3>Jerami: $7,500 · 75%</h3><p>Build work, development history, packaging, and originating the deal.</p><h3>Prospect ID: $2,500 · 25%</h3><p>Company operating records included in the approved scope. The company handles its internal allocation.</p></div><div><h3>Keep the agreement narrow.</h3><p>Define the company records licensed in this sale. Include embedded examples in that scope. Keep ownership of Jerami's original code.</p><p>Jev chose to wait for the buyer's price allocation. The 75/25 opening is my assessment of the contributions.</p><p><a href="ownership-and-split.md">Read the contribution and deal note ↗</a></p></div></div></section>
<footer><a href="README.md">Pack overview</a><a href="evidence.md">Evidence</a><a href="turing-brief.md">Turing brief</a><a href="ownership-and-split.md">Contribution and split</a><a href="review.source.json">Source facts</a><a href="verification.md">Checks</a></footer>
</main><script type="application/json" id="packet-data">@@DATA@@</script>
<script>
const packet=JSON.parse(document.getElementById('packet-data').textContent);
const tabs=[...document.querySelectorAll('[data-panel]')];
document.querySelector('.tabs').setAttribute('role','tablist');
function showPanel(id,focus=false){tabs.forEach(tab=>{const on=tab.dataset.panel===id;tab.setAttribute('role','tab');tab.setAttribute('aria-selected',String(on));tab.setAttribute('aria-controls',tab.dataset.panel);tab.tabIndex=on?0:-1;const panel=document.getElementById(tab.dataset.panel);panel.setAttribute('role','tabpanel');panel.hidden=!on;if(on&&focus)tab.focus();});}
tabs.forEach((tab,index)=>{tab.addEventListener('click',()=>showPanel(tab.dataset.panel));tab.addEventListener('keydown',event=>{let next;if(event.key==='ArrowRight')next=(index+1)%tabs.length;if(event.key==='ArrowLeft')next=(index+tabs.length-1)%tabs.length;if(event.key==='Home')next=0;if(event.key==='End')next=tabs.length-1;if(next!==undefined){event.preventDefault();showPanel(tabs[next].dataset.panel,true);}});});
showPanel('bridge');
const status=document.getElementById('status');
document.getElementById('copy-brief').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(packet.brief);status.textContent='Brief copied.';}catch{const range=document.createRange();range.selectNodeContents(document.getElementById('brief-text'));const selection=window.getSelection();selection.removeAllRanges();selection.addRange(range);status.textContent='Copy is blocked here. The brief is selected; use your copy shortcut.';}});
function save(name,content,type){const blob=new Blob([content],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);status.textContent='Download requested: '+name;}
document.getElementById('save-brief').addEventListener('click',()=>save('prospect-turing-brief.md',packet.brief,'text/markdown;charset=utf-8'));
document.getElementById('save-facts').addEventListener('click',()=>save('prospect-review.source.json',JSON.stringify(packet.source,null,2),'application/json'));
document.getElementById('print-report').addEventListener('click',()=>window.print());
</script></body></html>
'''

for key, value in {'STEPS': steps, 'HARD': hard_parts, 'EXAMPLES': examples, 'PRICES': prices, 'QUESTIONS': questions, 'BRIEF': esc(brief), 'DATA': embedded}.items():
    template = template.replace('@@' + key + '@@', value)
(BASE / 'review.html').write_text(template)
print(f'Rendered {BASE / "review.html"}: {len(template.encode())} bytes')
